import {emptyProfile, unknown, type SpotProfile, type Source} from './spotProfile.ts';
import {guideFacts, guideFactsFor} from './spotFactsSourced.ts';
import {mopAssignments, mopPoint} from './mop.ts';
import {profileFromGuide} from './spotFactsRules.ts';

/** Spot profile registry (T-041). Only facts with a published source are values; everything else is null.
 *  Drafts waiting for the owner are `proposal`s and show up in docs/forecast/SPOT-FACTS-REVIEW.md (generated by docs/forecast/data/build-spot-review.ts). */
const ON = '2026-11-02', CHECKED = '2026-10-20';
const cdipPage = (id: string): Source => ({url: `https://cdip.ucsd.edu/mops/?mop=${id}&xitem=info`, title: `CDIP MOP ${id} information page`, retrievedOn: CHECKED});
const cdipMeta = (id: string, quote: string): Source => ({url: `https://thredds.cdip.ucsd.edu/thredds/dodsC/cdip/model/MOP_alongshore/${id}_forecast.nc.ascii?metaLatitude,metaLongitude,metaWaterDepth,metaShoreNormal`, title: `CDIP MOP ${id} file metadata (OPeNDAP)`, retrievedOn: ON, quote});
const nps1: Source = {url: 'https://www.nps.gov/goga/planyourvisit/oceanbeach.htm', title: 'NPS Golden Gate NRA: Ocean Beach', retrievedOn: CHECKED};
const nps2: Source = {url: 'https://www.nps.gov/places/000/ocean-beach.htm', title: 'NPS: Ocean Beach (places)', retrievedOn: CHECKED};
const hansen: Source = {url: 'https://pubs.usgs.gov/publication/70112522', title: 'Hansen, Elias & Barnard (2013), Marine Geology 345:221–234, changes in surfzone morphodynamics at Ocean Beach', retrievedOn: ON, quote: 'migrated northward ~ 1 km toward the inlet'};
const barnard: Source = {url: 'https://pubs.usgs.gov/publication/70148290', title: 'Barnard, Hansen & Erikson (2012), J. Coastal Research, Ocean Beach erosion hot spot', retrievedOn: ON, quote: 'significant alongshore variability in forcing introduced by varying nearshore bathymetry'};
const marin: Source = {url: 'https://www.marincounty.gov/your-government/bolinas-wastewater', title: 'Marin County: Bolinas wastewater and beach sampling', retrievedOn: CHECKED};

const ob = emptyProfile('spot-2');
ob.mop = {value: {id: 'SF023', lat: 37.74811, lon: -122.51886, depthM: 10, shoreNormalDeg: 263.49}, status: 'sourced', sources: [cdipPage('SF023'), cdipMeta('SF023', 'metaWaterDepth, 10.0 · metaShoreNormal, 263.49')], note: 'A modelled point at 10 m depth, not the surf zone.'};
ob.orientation = {value: {beachNormalDeg: 263.49}, status: 'sourced', sources: [cdipMeta('SF023', 'metaShoreNormal, 263.49')], note: 'CDIP shore normal of that transect; it is not a statement about which swells the break uses.'};
ob.swellWindow = unknown('No published source. Engineering assumption from T-008: beach normal ±60° (offshore frame).', {value: {reference: 'offshore', fromDeg: 203, toDeg: 323}, sources: [], note: 'Engineering assumption (lead decision T-008), not a published fact. Replace with your local knowledge.'});
ob.periodResponse = unknown('No published source. Engineering assumption from T-008: 8 s minimum.', {value: {minUsefulS: 8}, sources: [], note: 'Engineering assumption (lead decision T-008), not a published fact. Replace with your local knowledge.'});
ob.bottom = unknown('USGS research describes mobile nearshore bars at Ocean Beach; no surf-break survey exists in the sources checked.', {value: {type: 'sand-bar', stability: 'mobile'}, sources: [hansen, barnard], note: 'Inference from USGS morphodynamics research (a transverse bar moved ~1 km 1956–2005; bathymetry varies along the beach). It is not a survey of the surf break and says nothing about the current bar.'});
ob.hazards = {value: ['Hazardous currents', 'Cold water'], status: 'sourced', sources: [nps1, nps2], note: 'From the NPS pages; not a complete hazard list.'};

const lm = emptyProfile('spot-3');
lm.mop = unknown('Candidates SM380–SM385: the transects whose back-beach ends CDIP places on Pacifica State Beach (one shared output point, 15 m deep). SM375/SM376, offered before, start on San Pedro Point. The facing-match rule picks among them.');

const bo = emptyProfile('spot-0');
bo.mop = unknown('Candidate MA140 (2.8 km away, 15 m deep, south-facing normal ~174°); the transect for the break is unknown.');
bo.hazards = {value: ['County documents bluff instability and contamination concerns in affected bluff-adjacent sections; check current advisories'], status: 'sourced', sources: [marin], note: 'County advisory text; not a current advisory feed.'};

// T-071: published spot-guide facts fill every fact a guide states and the profile does not already hold (reviewed or CDIP-sourced values are kept).
const withGuide = (p: SpotProfile): SpotProfile => { const f = guideFactsFor(p.spotId); return f ? profileFromGuide(f, p) : p; };
const guided = guideFacts.filter((f) => ![ob, lm, bo].some((p) => p.spotId === f.spotId)).map((f) => profileFromGuide(f));
const withMop = (p: SpotProfile): SpotProfile => { // a MOP point assigned by the facing-match rule (src/ocean/mop.ts) becomes the profile's MOP value
  const a = mopAssignments.find((x) => x.spotId === p.spotId), pt = a && mopPoint(a.mopId);
  return a && pt && p.mop.value === null ? {...p, mop: {value: {id: pt.id, lat: pt.lat, lon: pt.lon, depthM: pt.depthM, shoreNormalDeg: pt.shoreNormalDeg}, status: a.status, sources: [{url: `https://thredds.cdip.ucsd.edu/thredds/dodsC/cdip/model/MOP_alongshore/${pt.id}_forecast.nc.ascii?metaLatitude,metaLongitude,metaWaterDepth,metaShoreNormal`, title: `CDIP MOP ${pt.id} file metadata (OPeNDAP)`, retrievedOn: pt.retrievedOn}], provenance: 'agency data', note: a.note}} : p;
};
export const spotProfiles: SpotProfile[] = [ob, lm, bo].map(withGuide).concat(guided).map(withMop);
export const spotProfile = (spotId: string): SpotProfile | null => spotProfiles.find((p) => p.spotId === spotId) ?? null;
